import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {object}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate date format and reality
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) {
    return fail('DATE_INVALID');
  }
  const date = new Date(issueDate);
  if (date.toISOString().substring(0, 10) !== issueDate) {
    return fail('DATE_INVALID');
  }

  // Validate lines array
  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    enrichedLines.push({
      sku: line.sku,
      name: productResult.value.name,
      qty: line.qty,
      unitPrice: productResult.value.unitPrice,
      vatRate: productResult.value.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return { subtotal, total: subtotal };
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }}
 * @returns {object}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const newLines = invoice.lines.map(line => ({ ...line }));
  const existingIndex = newLines.findIndex(line => line.sku === sku);

  if (existingIndex >= 0) {
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku: sku,
      name: productResult.value.name,
      qty: qty,
      unitPrice: productResult.value.unitPrice,
      vatRate: productResult.value.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {object}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex(line => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

